select `tb_peserta`.`peserta_id` AS `peserta_id`,`tb_peserta`.`tgl_daftar` AS `tgl_daftar`,`tb_peserta`.`nama` AS `nama`,`tb_peserta`.`kelamin_id` AS `kelamin_id`,if((`tb_peserta`.`kelamin_id` = 1),'P',if((`tb_peserta`.`kelamin_id` = 2),'P','-')) AS `kelamin`,`tb_peserta`.`kelas_id` AS `kelas_id`,`mt_kelas`.`kelas` AS `kelas`,`mt_kelas`.`teori_id` AS `teori_id`,`tb_peserta`.`biaya` AS `biaya`,`tb_peserta`.`teori_hadir` AS `teori_hadir`,`tb_peserta`.`teori_tgl` AS `teori_tgl`,`tb_peserta`.`teori_kode` AS `teori_kode`,`tb_peserta`.`teori_nilai` AS `teori_nilai`,`tb_peserta`.`teori_hasil` AS `teori_hasil`,`tb_peserta`.`teori_cetak` AS `teori_cetak`,`tb_peserta`.`teori_log` AS `teori_log`,`tb_peserta`.`operator_id` AS `operator_id`,`tb_peserta`.`client_id` AS `client_id`,`tb_peserta`.`a_kunci` AS `a_kunci`,`tb_peserta`.`a_jawab` AS `a_jawab`,`tb_peserta`.`penguji` AS `penguji`,`tb_peserta`.`sertif_nomor` AS `sertif_nomor`,`tb_peserta`.`sertif_tanggal` AS `sertif_tanggal`,`tb_peserta`.`sertif_cetak` AS `sertif_cetak`,`tb_peserta`.`counter` AS `counter`,`tb_peserta`.`tgl_input` AS `tgl_input`,`tb_peserta`.`tgl_update` AS `tgl_update`,`tb_peserta`.`user_id` AS `user_id`,`mt_user`.`user_name` AS `user_name`,`mt_app`.`app` AS `app`,year(`tb_peserta`.`tgl_daftar`) AS `tahun`,month(`tb_peserta`.`tgl_daftar`) AS `bulan`,dayofmonth(`tb_peserta`.`tgl_daftar`) AS `tgl`,`tb_peserta`.`praktek_hasil` AS `praktek_hasil`,`tb_peserta`.`praktek_id` AS `praktek_id`
from `tb_peserta`
join `mt_kelas` on `tb_peserta`.`kelas_id` = `mt_kelas`.`kelas_id` and tb_peserta.area_id = mt_kelas.area_id
join `mt_user` on `tb_peserta`.`user_id` = `mt_user`.`user_id`
join `mt_app` on `mt_user`.`app_id` = `mt_app`.`app_id`
